// Render serves human- and AI-readable Markdown pages over gnoweb.
func Render(path string) string {
	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, req *mux.Request) {
	filter := strings.ToUpper(strings.TrimSpace(req.Query.Get("status")))

	res.Write("# BountyForge — On-Chain Micro-Bounty Escrow & Builder Reputation\n\n")
	res.Write("Trustless GNOT escrow, dust-free basis-point split payouts, optional arbiter dispute resolution, and verifiable builder XP on Gno.land.\n\n")
	res.Write(ufmt.Sprintf(
		"**Locked Escrow:** %s | **Total Paid:** %s | **Open:** %d | **Paid:** %d | **Disputed:** %d | **Builders:** %d\n\n",
		escrowmath.FormatGNOT(totalEscrowed),
		escrowmath.FormatGNOT(totalPaidOut),
		openCount,
		paidCount,
		disputedCount,
		builders.Size(),
	))
	res.Write("[All](:) · [Open](:?status=OPEN) · [Paid](:?status=PAID) · [Disputed](:?status=DISPUTED) · [Leaderboard](:leaderboard) · [Protocol Stats](:stats)\n\n")

	if bounties.Size() == 0 {
		res.Write("_No bounties posted yet. Call `CreateBounty` with `-send` GNOT to fund the first quest!_\n")
		return
	}

	res.Write("| ID | Title | Reward | Status | Submissions | Tags |\n")
	res.Write("|---|---|---|---|---|---|\n")

	shown := 0
	bounties.ReverseIterate("", "", func(_ string, val any) bool {
		b := val.(*Bounty)
		if filter != "" && b.Status != filter {
			return false
		}
		res.Write(ufmt.Sprintf(
			"| [#%d](:bounty/%d) | %s | %s | `%s` | %d | %s |\n",
			b.ID,
			b.ID,
			b.Title,
			escrowmath.FormatGNOT(b.RewardUgnot),
			b.Status,
			len(b.Submissions),
			b.Tags,
		))
		shown++
		return shown >= 50
	})

	if shown == 0 {
		res.Write(ufmt.Sprintf("\n_No bounties match status `%s`._\n", escrowmath.SanitizeInline(filter, 20)))
	}
}

func renderBountyDetail(res *mux.ResponseWriter, req *mux.Request) {
	rawID := req.GetVar("id")
	idNum, err := strconv.ParseUint(rawID, 10, 64)
	if err != nil || idNum == 0 {
		res.Write("# Invalid Bounty ID\n\n[Back to Board](:)\n")
		return
	}
	raw := bounties.Get(seqid.ID(idNum).String())
	if raw == nil {
		res.Write(ufmt.Sprintf("# Bounty #%d Not Found\n\n[Back to Board](:)\n", idNum))
		return
	}
	b := raw.(*Bounty)

	res.Write(ufmt.Sprintf("# Bounty #%d: %s\n\n", b.ID, b.Title))
	res.Write(ufmt.Sprintf("- **Status:** `%s`\n", b.Status))
	res.Write(ufmt.Sprintf("- **Reward Pool:** %s (`%d ugnot`)\n", escrowmath.FormatGNOT(b.RewardUgnot), b.RewardUgnot))
	res.Write(ufmt.Sprintf("- **Creator:** `%s`\n", b.Creator.String()))
	if b.Arbiter != "" {
		res.Write(ufmt.Sprintf("- **Dispute Arbiter:** `%s`\n", b.Arbiter.String()))
	} else {
		res.Write("- **Dispute Arbiter:** _None (creator-managed)_\n")
	}
	if b.DeadlineH > 0 {
		res.Write(ufmt.Sprintf("- **Deadline Height:** #%d (current: #%d)\n", b.DeadlineH, runtime.ChainHeight()))
	} else {
		res.Write("- **Deadline Height:** _No expiry_\n")
	}
	if b.Tags != "" {
		res.Write(ufmt.Sprintf("- **Tags:** `%s`\n", b.Tags))
	}
	res.Write("\n## Specification\n\n" + b.Summary + "\n\n")

	if b.DisputeReason != "" {
		res.Write("## Dispute Notice\n\n> " + b.DisputeReason + "\n\n")
	}

	res.Write(ufmt.Sprintf("## Submissions (%d)\n\n", len(b.Submissions)))
	if len(b.Submissions) == 0 {
		res.Write("_No submissions yet._\n\n")
	} else {
		res.Write("| # | Builder | Proof | Notes | Block |\n")
		res.Write("|---|---|---|---|---|\n")
		for _, sub := range b.Submissions {
			res.Write(ufmt.Sprintf(
				"| %d | [%s](:builder/%s) | %s | %s | #%d |\n",
				sub.Index,
				shortAddr(sub.Builder),
				sub.Builder.String(),
				sub.ProofURL,
				sub.Notes,
				sub.SubmittedH,
			))
		}
		res.Write("\n")
	}

	if len(b.Payouts) > 0 {
		res.Write("## On-Chain Settlement\n\n")
		res.Write("| Recipient | Share | Amount |\n")
		res.Write("|---|---|---|\n")
		for _, p := range b.Payouts {
			res.Write(ufmt.Sprintf(
				"| [%s](:builder/%s) | %.2f%% | %s |\n",
				shortAddr(p.Recipient),
				p.Recipient.String(),
				float64(p.Bps)/100.0,
				escrowmath.FormatGNOT(p.Amount),
			))
		}
		res.Write("\n")
	}

	res.Write("[Back to Board](:) · [Leaderboard](:leaderboard)\n")
}

func renderBuilderProfile(res *mux.ResponseWriter, req *mux.Request) {
	addrStr := escrowmath.SanitizeInline(req.GetVar("addr"), 64)
	raw := builders.Get(addrStr)
	res.Write("# Builder Profile\n\n")
	res.Write(ufmt.Sprintf("- **Address:** `%s`\n", addrStr))
	if raw == nil {
		res.Write("- **Tier:** `[N]` Novice\n- **XP:** 0\n- **Completed Bounties:** 0\n\n")
		res.Write("[Back to Board](:) · [Leaderboard](:leaderboard)\n")
		return
	}
	prof := raw.(*BuilderProfile)
	tier, badge := escrowmath.TierForXP(prof.XP)
	nextTarget := nextTierTarget(prof.XP)
	res.Write(ufmt.Sprintf("- **Tier:** `%s` %s\n", badge, tier))
	res.Write(ufmt.Sprintf("- **Reputation XP:** %d %s\n", prof.XP, escrowmath.ProgressBar(int(prof.XP), int(nextTarget), 12)))
	res.Write(ufmt.Sprintf("- **Completed Bounties:** %d\n", prof.Completed))
	res.Write(ufmt.Sprintf("- **Total Earned:** %s\n", escrowmath.FormatGNOT(prof.TotalEarned)))
	res.Write(ufmt.Sprintf("- **Last Active Block:** #%d\n\n", prof.LastHeight))
	res.Write("[Back to Board](:) · [Leaderboard](:leaderboard)\n")
}

func renderLeaderboard(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write("# BountyForge Builder Leaderboard\n\n")
	if builders.Size() == 0 {
		res.Write("_No settled bounties yet._\n\n[Back to Board](:)\n")
		return
	}

	list := make([]*BuilderProfile, 0, builders.Size())
	builders.Iterate("", "", func(_ string, val any) bool {
		list = append(list, val.(*BuilderProfile))
		return false
	})

	// Deterministic insertion sort by XP desc, then TotalEarned desc, then Address asc.
	for i := 1; i < len(list); i++ {
		cur := list[i]
		j := i - 1
		for j >= 0 && betterProfile(cur, list[j]) {
			list[j+1] = list[j]
			j--
		}
		list[j+1] = cur
	}

	res.Write("| Rank | Builder | Tier | XP | Completed | Earned |\n")
	res.Write("|---|---|---|---|---|---|\n")
	for i, prof := range list {
		tier, badge := escrowmath.TierForXP(prof.XP)
		res.Write(ufmt.Sprintf(
			"| %d | [%s](:builder/%s) | `%s` %s | %d | %d | %s |\n",
			i+1,
			shortAddr(prof.Address),
			prof.Address.String(),
			badge,
			tier,
			prof.XP,
			prof.Completed,
			escrowmath.FormatGNOT(prof.TotalEarned),
		))
	}
	res.Write("\n[Back to Board](:) · [Protocol Stats](:stats)\n")
}

func renderStats(res *mux.ResponseWriter, _ *mux.Request) {
	res.Write("# BountyForge Protocol Stats\n\n")
	res.Write(ufmt.Sprintf("- **Total Bounties:** %d\n", bounties.Size()))
	res.Write(ufmt.Sprintf("- **Open:** %d | **Paid:** %d | **Disputed:** %d | **Cancelled:** %d\n", openCount, paidCount, disputedCount, cancelledCnt))
	res.Write(ufmt.Sprintf("- **Total Locked Escrow:** %s (`%d ugnot`)\n", escrowmath.FormatGNOT(totalEscrowed), totalEscrowed))
	res.Write(ufmt.Sprintf("- **Cumulative Paid Out:** %s (`%d ugnot`)\n", escrowmath.FormatGNOT(totalPaidOut), totalPaidOut))
	res.Write(ufmt.Sprintf("- **Verified Builders:** %d\n", builders.Size()))
	res.Write(ufmt.Sprintf("- **Current Block Height:** #%d\n\n", runtime.ChainHeight()))
	res.Write("[Back to Board](:) · [Leaderboard](:leaderboard)\n")
}

func betterProfile(a, b *BuilderProfile) bool {
	if a.XP != b.XP {
		return a.XP > b.XP
	}
	if a.TotalEarned != b.TotalEarned {
		return a.TotalEarned > b.TotalEarned
	}
	return a.Address.String() < b.Address.String()
}

func nextTierTarget(xp int64) int64 {
	switch {
	case xp < 100:
		return 100
	case xp < 300:
		return 300
	case xp < 800:
		return 800
	case xp < 2000:
		return 2000
	case xp < 5000:
		return 5000
	default:
		return xp
	}
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "..." + s[len(s)-4:]
}

// Package gnometavern is "The Gnome Tavern": a fully on-chain tavern on
// Gno.land, built for The Gnome Tavern Hackathon (DoraHacks).
//
// Gnomes (users) check in at the door, order drinks from the menu with real
// testnet ugnot, tip the keeper, and complete daily quests. Every visit,
// drink, tip and quest point lives in this realm's state — there is no
// backend and no external database. The Render function is the tavern's
// public notice board, readable by anyone through gnoweb.
//
// Payment safety: functions that accept native coins (OrderDrink, Tip)
// follow the pattern from the Gno security guide — the caller must be a
// direct EOA call (cur.Previous().IsUserCall()) and the amount is read from
// unsafe.OriginSend(). Kept together, the pair guarantees the coins checked
// are the coins that actually landed at this realm's address.
package gnometavern

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
)

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

// MenuItem is one drink on the tavern menu. Price is in ugnot
// (1 GNOT = 1_000_000 ugnot). Stock counts the drinks left in the keg.
type MenuItem struct {
	Name  string
	Price int64
	Stock int64
}

// Quest is one entry on the tavern quest board. A patron can complete each
// quest at most once per day (day = unix day of chain time).
type Quest struct {
	Title  string
	Points int64
}

// Patron is the tavern's record of one gnome.
type Patron struct {
	Nickname    string
	Visits      int64
	Drinks      int64
	TipsPaid    int64 // ugnot, overpayments + explicit tips
	QuestPoints int64
}

// ---------------------------------------------------------------------------
// State (persisted by the GnoVM between transactions)
// ---------------------------------------------------------------------------

var (
	keeper address // the tavern keeper (deployer); only address that manages menu/quests

	menu   []*MenuItem
	quests []*Quest

	patrons     map[string]*Patron // key: patron address string
	patronOrder []string           // patron address strings, in first-visit order

	totalVisits int64
	totalDrinks int64
	till        int64 // total ugnot received by the tavern (drink payments + tips)

	// lastQuestClaim maps "<addr>#<questID>" to the unix day of the last claim.
	lastQuestClaim map[string]int64
)

// init runs once, when the realm is deployed. The previous realm during
// initialization is the publisher (the EOA that deployed the realm), so the
// keeper is captured from it rather than hardcoded.
func init(cur realm) {
	keeper = cur.Previous().Address()
	seed()
}

// seed (re)builds the opening menu and quest board. It is also used by the
// unit tests to reset state.
func seed() {
	menu = []*MenuItem{
		{Name: "Gnome Ale", Price: 50000, Stock: 40},
		{Name: "Mushroom Stout", Price: 80000, Stock: 30},
		{Name: "Crystal Cider", Price: 70000, Stock: 30},
		{Name: "Stardust Mead", Price: 120000, Stock: 20},
		{Name: "Dragonfire Whisky", Price: 250000, Stock: 10},
	}
	quests = []*Quest{
		{Title: "First Steps: check in at the tavern door", Points: 5},
		{Title: "Thirsty Work: order any drink from the menu", Points: 5},
		{Title: "Generous Soul: leave the keeper a tip", Points: 10},
		{Title: "Tavern Regular: come back on another day", Points: 10},
	}
	patrons = make(map[string]*Patron)
	patronOrder = nil
	totalVisits = 0
	totalDrinks = 0
	till = 0
	lastQuestClaim = make(map[string]int64)
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// getOrCreatePatron returns the caller's patron record, creating an empty
// one on first interaction.
func getOrCreatePatron(addr address) *Patron {
	key := addr.String()
	if p, ok := patrons[key]; ok {
		return p
	}
	p := &Patron{}
	patrons[key] = p
	patronOrder = append(patronOrder, key)
	return p
}

// scoreOf computes a patron's Hall of Fame score:
// 1 pt per visit, 2 pts per drink, quest points as-is,
// plus 1 pt per full 0.1 GNOT (100_000 ugnot) tipped.
func scoreOf(p *Patron) int64 {
	return p.Visits + 2*p.Drinks + p.QuestPoints + p.TipsPaid/100000
}

// currentDay returns the current unix day according to chain time.
func currentDay() int64 {
	return time.Now().Unix() / 86400
}

// cleanText validates user-supplied display text (nicknames, menu and quest
// names). It rejects empty/overlong strings and characters that would break
// the markdown notice board.
func cleanText(s string, maxLen int) string {
	s = strings.TrimSpace(s)
	if s == "" {
		panic("text must not be empty")
	}
	if len(s) > maxLen {
		panic("text is too long")
	}
	if strings.ContainsAny(s, "|\n\r<>") {
		panic("text contains forbidden characters")
	}
	return s
}

// requireKeeper panics unless the caller is the tavern keeper.
func requireKeeper(cur realm) {
	if cur.Previous().Address() != keeper {
		panic("only the tavern keeper can do that")
	}
}

// requireUserPayment enforces the payment-guard pair for coin-accepting
// entry points and returns the ugnot amount attached to the transaction.
func requireUserPayment(cur realm) int64 {
	if !cur.Previous().IsUserCall() {
		panic("must be called directly by a user (maketx call)")
	}
	return unsafe.OriginSend().AmountOf("ugnot")
}

// ---------------------------------------------------------------------------
// Public entry points
// ---------------------------------------------------------------------------

// CheckIn registers the caller as a patron (first call) and records a visit.
// The nickname is set on the first check-in only; later calls keep the
// original name so nobody can rename somebody else's gnome.
func CheckIn(cur realm, nickname string) string {
	caller := cur.Previous().Address()
	key := caller.String()
	p, known := patrons[key]
	if !known {
		p = getOrCreatePatron(caller)
		p.Nickname = cleanText(nickname, 24)
	}
	p.Visits++
	totalVisits++
	return "Welcome to the Gnome Tavern, " + p.Nickname + "! Visit #" +
		strconv.FormatInt(p.Visits, 10) + "."
}

// OrderDrink serves one drink from the menu. The caller must attach at
// least the menu price in ugnot to the call (-send). Any overpayment is
// recorded as a tip to the keeper.
func OrderDrink(cur realm, itemID int64) string {
	sent := requireUserPayment(cur)
	if itemID < 0 || itemID >= int64(len(menu)) {
		panic("no such drink on the menu")
	}
	item := menu[itemID]
	if item.Stock <= 0 {
		panic("the keg is empty: " + item.Name + " is sold out")
	}
	if sent < item.Price {
		panic("not enough ugnot sent for " + item.Name)
	}
	caller := cur.Previous().Address()
	p := getOrCreatePatron(caller)

	item.Stock--
	p.Drinks++
	totalDrinks++
	till += sent
	if over := sent - item.Price; over > 0 {
		p.TipsPaid += over
	}
	return "The keeper slides a " + item.Name + " across the bar. Cheers, " +
		displayName(p, caller) + "!"
}

// Tip leaves the keeper a tip. The full amount attached to the call
// (-send, in ugnot) is recorded as a tip from the caller.
func Tip(cur realm) string {
	sent := requireUserPayment(cur)
	if sent <= 0 {
		panic("a tip must send some ugnot")
	}
	caller := cur.Previous().Address()
	p := getOrCreatePatron(caller)
	p.TipsPaid += sent
	till += sent
	return "The keeper bows. " + displayName(p, caller) + " tipped " +
		strconv.FormatInt(sent, 10) + "ugnot."
}

// CompleteQuest claims the points of one quest from the board. Each patron
// can complete a given quest at most once per day.
func CompleteQuest(cur realm, questID int64) string {
	if questID < 0 || questID >= int64(len(quests)) {
		panic("no such quest on the board")
	}
	caller := cur.Previous().Address()
	key := caller.String() + "#" + strconv.FormatInt(questID, 10)
	day := currentDay()
	if last, ok := lastQuestClaim[key]; ok && last == day {
		panic("quest already completed today — come back tomorrow")
	}
	lastQuestClaim[key] = day
	q := quests[questID]
	p := getOrCreatePatron(caller)
	p.QuestPoints += q.Points
	return "Quest complete: \"" + q.Title + "\" (+" +
		strconv.FormatInt(q.Points, 10) + " pts)."
}

// AddMenuItem puts a new drink on the menu. Keeper only.
func AddMenuItem(cur realm, name string, price int64, stock int64) string {
	requireKeeper(cur)
	if price <= 0 {
		panic("price must be positive")
	}
	if stock < 0 {
		panic("stock must not be negative")
	}
	menu = append(menu, &MenuItem{
		Name:  cleanText(name, 32),
		Price: price,
		Stock: stock,
	})
	return "Added to the menu: " + name
}

// Restock adds drinks to an existing keg. Keeper only.
func Restock(cur realm, itemID int64, amount int64) string {
	requireKeeper(cur)
	if itemID < 0 || itemID >= int64(len(menu)) {
		panic("no such drink on the menu")
	}
	if amount <= 0 {
		panic("restock amount must be positive")
	}
	menu[itemID].Stock += amount
	return "Restocked " + menu[itemID].Name + " by " +
		strconv.FormatInt(amount, 10) + "."
}

// AddQuest pins a new quest on the board. Keeper only.
func AddQuest(cur realm, title string, points int64) string {
	requireKeeper(cur)
	if points <= 0 {
		panic("quest points must be positive")
	}
	quests = append(quests, &Quest{
		Title:  cleanText(title, 64),
		Points: points,
	})
	return "New quest on the board: " + title
}

// ---------------------------------------------------------------------------
// Read-only getters (handy for judges and scripts)
// ---------------------------------------------------------------------------

// GetStats returns the tavern's headline numbers.
func GetStats() (visits int64, drinks int64, tillAmount int64, patronCount int64) {
	return totalVisits, totalDrinks, till, int64(len(patronOrder))
}

// GetPatron returns one patron's record by address.
func GetPatron(addr address) (nickname string, visits int64, drinks int64, tipsPaid int64, questPoints int64, score int64, found bool) {
	p, ok := patrons[addr.String()]
	if !ok {
		return "", 0, 0, 0, 0, 0, false
	}
	return p.Nickname, p.Visits, p.Drinks, p.TipsPaid, p.QuestPoints, scoreOf(p), true
}

// displayName returns the patron's nickname, or a short form of their
// address when they never set one.
func displayName(p *Patron, addr address) string {
	if p.Nickname != "" {
		return p.Nickname
	}
	return addr.String()
}

// ---------------------------------------------------------------------------
// Render — the tavern notice board (gnoweb)
// ---------------------------------------------------------------------------

// Render serves the realm's pages:
//
//	""               the main board: stats, menu, quest board, Hall of Fame
//	"menu"           the menu only
//	"quests"         the quest board only
//	"patron/<addr>"  one patron's card
func Render(path string) string {
	switch {
	case path == "" :
		return renderHome()
	case path == "menu":
		return renderMenu()
	case path == "quests":
		return renderQuests()
	case strings.HasPrefix(path, "patron/"):
		return renderPatron(strings.TrimPrefix(path, "patron/"))
	default:
		return "# The Gnome Tavern\n\nNo such page at the tavern. Try the [main board](/)."
	}
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# 🍺 The Gnome Tavern\n\n")
	b.WriteString("An on-chain tavern on Gno.land. Check in, order a drink, tip the keeper, finish a quest — everything is recorded in this realm, no backend involved.\n\n")
	b.WriteString("**Keeper:** `" + keeper.String() + "`\n\n")
	b.WriteString("| Stat | Value |\n| --- | --- |\n")
	b.WriteString("| Total check-ins | " + strconv.FormatInt(totalVisits, 10) + " |\n")
	b.WriteString("| Drinks served | " + strconv.FormatInt(totalDrinks, 10) + " |\n")
	b.WriteString("| Registered patrons | " + strconv.Itoa(len(patronOrder)) + " |\n")
	b.WriteString("| Tavern till | " + strconv.FormatInt(till, 10) + " ugnot |\n\n")
	b.WriteString(renderMenu())
	b.WriteString("\n")
	b.WriteString(renderQuests())
	b.WriteString("\n")
	b.WriteString(renderHallOfFame())
	return b.String()
}

func renderMenu() string {
	var b strings.Builder
	b.WriteString("## 🍻 Menu\n\n")
	b.WriteString("| # | Drink | Price (ugnot) | In the keg |\n| --- | --- | --- | --- |\n")
	for i, item := range menu {
		b.WriteString("| " + strconv.Itoa(i) + " | " + item.Name + " | " +
			strconv.FormatInt(item.Price, 10) + " | " +
			strconv.FormatInt(item.Stock, 10) + " |\n")
	}
	b.WriteString("\nOrder with `OrderDrink(<id>)` and attach the price with `-send`.\n")
	return b.String()
}

func renderQuests() string {
	var b strings.Builder
	b.WriteString("## 📜 Quest board\n\n")
	b.WriteString("| # | Quest | Points |\n| --- | --- | --- |\n")
	for i, q := range quests {
		b.WriteString("| " + strconv.Itoa(i) + " | " + q.Title + " | " +
			strconv.FormatInt(q.Points, 10) + " |\n")
	}
	b.WriteString("\nEach quest can be completed once per patron per day with `CompleteQuest(<id>)`.\n")
	return b.String()
}

// renderHallOfFame lists the top 10 patrons by score.
func renderHallOfFame() string {
	var b strings.Builder
	b.WriteString("## 🏆 Hall of Fame\n\n")
	if len(patronOrder) == 0 {
		b.WriteString("No patrons yet — be the first gnome through the door (`CheckIn`).\n")
		return b.String()
	}
	// Rank patrons by score, descending (insertion sort on a copy of the
	// address list; the tavern is small and Render must stay cheap).
	ranked := make([]string, len(patronOrder))
	copy(ranked, patronOrder)
	for i := 1; i < len(ranked); i++ {
		for j := i; j > 0 && scoreOf(patrons[ranked[j]]) > scoreOf(patrons[ranked[j-1]]); j-- {
			ranked[j], ranked[j-1] = ranked[j-1], ranked[j]
		}
	}
	b.WriteString("| Rank | Patron | Visits | Drinks | Quest pts | Tips (ugnot) | Score |\n")
	b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
	limit := len(ranked)
	if limit > 10 {
		limit = 10
	}
	for i := 0; i < limit; i++ {
		addr := ranked[i]
		p := patrons[addr]
		b.WriteString("| " + strconv.Itoa(i+1) + " | [" + displayName(p, address(addr)) +
			"](/patron/" + addr + ") | " +
			strconv.FormatInt(p.Visits, 10) + " | " +
			strconv.FormatInt(p.Drinks, 10) + " | " +
			strconv.FormatInt(p.QuestPoints, 10) + " | " +
			strconv.FormatInt(p.TipsPaid, 10) + " | " +
			strconv.FormatInt(scoreOf(p), 10) + " |\n")
	}
	return b.String()
}

func renderPatron(addrStr string) string {
	p, ok := patrons[addrStr]
	if !ok {
		return "# Patron card\n\n`" + addrStr + "` has never visited the Gnome Tavern."
	}
	var b strings.Builder
	b.WriteString("# 🧙 Patron card\n\n")
	b.WriteString("**Name:** " + displayName(p, address(addrStr)) + "\n\n")
	b.WriteString("**Address:** `" + addrStr + "`\n\n")
	b.WriteString("| Stat | Value |\n| --- | --- |\n")
	b.WriteString("| Check-ins | " + strconv.FormatInt(p.Visits, 10) + " |\n")
	b.WriteString("| Drinks ordered | " + strconv.FormatInt(p.Drinks, 10) + " |\n")
	b.WriteString("| Quest points | " + strconv.FormatInt(p.QuestPoints, 10) + " |\n")
	b.WriteString("| Tips paid | " + strconv.FormatInt(p.TipsPaid, 10) + " ugnot |\n")
	b.WriteString("| Hall of Fame score | " + strconv.FormatInt(scoreOf(p), 10) + " |\n")
	return b.String()
}

package gnometavern

import (
	"chain"
	"strings"
	"testing"
	"time"
)

// Test addresses borrowed from the gno repository's own example tests
// (deterministic, valid bech32 — no private keys behind them).
var (
	keeperAddr = address("g1wdjkuer9wgc47h6lta047h6lta047h6l56jtjc")
	aliceAddr  = address("g1wfjkx6tsd9jkuap3ta047h6lta047h6lkk20gv")
	bobAddr    = address("g1v9kxjcm9ta047h6lta047h6lta047h6lzd40gh")
)

// reset returns the tavern to its opening state with a known keeper.
func reset() {
	keeper = keeperAddr
	seed()
}

// IMPORTANT testing notes (learned the hard way on gno v1.8):
//   - testing.SetRealm / testing.SetOriginSend must be called INLINE in
//     the test body; calling them from a helper function does not stick.
//   - The origin send must be set BEFORE the realm: SetOriginSend
//     round-trips the context without CurrentRealm and would clobber it.
//   - Realm panics cross a crossing boundary where plain recover() cannot
//     catch them; the revive() builtin exists for exactly this.

// --- tiny assertion helpers (kept local so the tests need no downloads) ---

func eqI64(t *testing.T, want, got int64, what string) {
	t.Helper()
	if want != got {
		t.Fatalf("%s: want %d, got %d", what, want, got)
	}
}

func eqStr(t *testing.T, want, got string, what string) {
	t.Helper()
	if want != got {
		t.Fatalf("%s: want %q, got %q", what, want, got)
	}
}

func isTrue(t *testing.T, cond bool, what string) {
	t.Helper()
	if !cond {
		t.Fatalf("expected true: %s", what)
	}
}

func contains(t *testing.T, s, sub string) {
	t.Helper()
	if !strings.Contains(s, sub) {
		t.Fatalf("expected %q to contain %q", s, sub)
	}
}

// abortsWith runs fn and requires it to panic with a message containing sub.
func abortsWith(t *testing.T, sub string, fn func()) {
	t.Helper()
	r := revive(fn)
	if r == nil {
		t.Fatalf("expected panic containing %q, but the call succeeded", sub)
	}
	msg := ""
	switch v := r.(type) {
	case string:
		msg = v
	case error:
		msg = v.Error()
	default:
		msg = "unprintable panic"
	}
	if !strings.Contains(msg, sub) {
		t.Fatalf("panic %q does not contain %q", msg, sub)
	}
}

// --- tests ---

func TestCheckIn(cur realm, t *testing.T) {
	reset()

	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	msg := CheckIn(cross(cur), "AliceTheGnome")
	contains(t, msg, "AliceTheGnome")

	_, visits, _, _, _, _, found := GetPatron(aliceAddr)
	isTrue(t, found, "patron exists after check-in")
	eqI64(t, 1, visits, "visits after first check-in")

	// Second visit: counter grows, original nickname is kept.
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	CheckIn(cross(cur), "SomeOtherName")
	nick, visits, _, _, _, _, _ := GetPatron(aliceAddr)
	eqStr(t, "AliceTheGnome", nick, "nickname locked after first check-in")
	eqI64(t, 2, visits, "visits after second check-in")

	v, _, _, pc := GetStats()
	eqI64(t, 2, v, "total visits")
	eqI64(t, 1, pc, "patron count")
}

func TestOrderDrink(cur realm, t *testing.T) {
	reset()

	// Exact payment for a Gnome Ale (item 0, price 50000, stock 40).
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 50000}})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	OrderDrink(cross(cur), 0)
	eqI64(t, 39, menu[0].Stock, "stock after one order")
	_, _, drinks, tips, _, _, _ := GetPatron(aliceAddr)
	eqI64(t, 1, drinks, "drinks after one order")
	eqI64(t, 0, tips, "no tip on exact payment")
	_, d, tillAmt, _ := GetStats()
	eqI64(t, 1, d, "total drinks")
	eqI64(t, 50000, tillAmt, "till after one order")

	// Overpayment is recorded as a tip.
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 60000}})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	OrderDrink(cross(cur), 0)
	_, _, _, tips, _, _, _ = GetPatron(aliceAddr)
	eqI64(t, 10000, tips, "overpayment recorded as tip")

	// Underpayment aborts and changes nothing.
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 49999}})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	abortsWith(t, "not enough ugnot", func() {
		OrderDrink(cross(cur), 0)
	})
	eqI64(t, 38, menu[0].Stock, "stock unchanged after failed order")

	// Unknown item aborts.
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 999999}})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	abortsWith(t, "no such drink", func() {
		OrderDrink(cross(cur), 99)
	})

	// Sold-out keg aborts.
	menu[0].Stock = 0
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 50000}})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	abortsWith(t, "sold out", func() {
		OrderDrink(cross(cur), 0)
	})
}

func TestTip(cur realm, t *testing.T) {
	reset()

	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 123456}})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	Tip(cross(cur))
	_, _, _, tips, _, score, _ := GetPatron(bobAddr)
	eqI64(t, 123456, tips, "tip recorded")
	eqI64(t, 1, score, "score: 123456/100000 = 1 pt")
	_, _, tillAmt, _ := GetStats()
	eqI64(t, 123456, tillAmt, "till after tip")

	// A tip without coins aborts.
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	abortsWith(t, "must send some ugnot", func() {
		Tip(cross(cur))
	})
}

func TestCompleteQuest(cur realm, t *testing.T) {
	reset()

	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	CompleteQuest(cross(cur), 2) // "Generous Soul", 10 pts
	_, _, _, _, qp, _, _ := GetPatron(aliceAddr)
	eqI64(t, 10, qp, "quest points after first claim")

	// Same quest again on the same day aborts.
	abortsWith(t, "already completed today", func() {
		CompleteQuest(cross(cur), 2)
	})

	// A different quest the same day is fine.
	CompleteQuest(cross(cur), 0)
	_, _, _, _, qp, _, _ = GetPatron(aliceAddr)
	eqI64(t, 15, qp, "quest points after second quest")

	// Next day (chain time +25h) the first quest can be claimed again.
	ctx := testing.GetContext()
	ctx.Time = ctx.Time.Add(25 * time.Hour)
	testing.SetContext(ctx)
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	CompleteQuest(cross(cur), 2)
	_, _, _, _, qp, _, _ = GetPatron(aliceAddr)
	eqI64(t, 25, qp, "quest points after next-day claim")

	// Unknown quest aborts.
	abortsWith(t, "no such quest", func() {
		CompleteQuest(cross(cur), 42)
	})
}

func TestKeeperOnly(cur realm, t *testing.T) {
	reset()

	// A random patron cannot manage the menu or the board.
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	abortsWith(t, "only the tavern keeper", func() {
		AddMenuItem(cross(cur), "Sneaky Brew", 1000, 5)
	})
	abortsWith(t, "only the tavern keeper", func() {
		Restock(cross(cur), 0, 5)
	})
	abortsWith(t, "only the tavern keeper", func() {
		AddQuest(cross(cur), "Sneaky Quest", 5)
	})

	// The keeper can.
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(keeperAddr))
	AddMenuItem(cross(cur), "Golden Mead Deluxe", 300000, 7)
	eqI64(t, 6, int64(len(menu)), "menu length after keeper add")
	Restock(cross(cur), 0, 10)
	eqI64(t, 50, menu[0].Stock, "stock after restock")
	AddQuest(cross(cur), "Sing a shanty on the bar", 15)
	eqI64(t, 5, int64(len(quests)), "quest count after keeper add")
}

func TestRender(cur realm, t *testing.T) {
	reset()

	home := Render("")
	contains(t, home, "The Gnome Tavern")
	contains(t, home, "Gnome Ale")
	contains(t, home, "Quest board")
	contains(t, home, "No patrons yet")

	unknown := Render("patron/" + bobAddr.String())
	contains(t, unknown, "has never visited")

	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	CheckIn(cross(cur), "AliceTheGnome")
	card := Render("patron/" + aliceAddr.String())
	contains(t, card, "AliceTheGnome")
	contains(t, card, "Check-ins | 1")

	home = Render("")
	contains(t, home, "AliceTheGnome")

	bad := Render("cellar")
	contains(t, bad, "No such page")
}

func TestHallOfFameRanking(cur realm, t *testing.T) {
	reset()

	// Alice: 1 visit (1 pt). Bob: 1 visit + big tip (1 + 3 pts).
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	CheckIn(cross(cur), "Alice")
	testing.SetOriginSend(chain.Coins{})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	CheckIn(cross(cur), "Bob")
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 300000}})
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	Tip(cross(cur))

	home := Render("")
	idxBob := strings.Index(home, "[Bob]")
	idxAlice := strings.Index(home, "[Alice]")
	isTrue(t, idxBob >= 0 && idxAlice >= 0, "both patrons listed in Hall of Fame")
	isTrue(t, idxBob < idxAlice, "higher score must rank first")
}

package counter

import "strconv"

var counter int

func Increment(_ realm) int {
	counter++
	return counter
}

func Render(_ string) string {
	return strconv.Itoa(counter)
}

package counter

import "testing"

func TestIncrement(cur realm, t *testing.T) {
	counter = 0
	val := Increment(cross(cur))
	if val != 1 {
		t.Fatalf("result from Increment(): %d != 1", val)
	}
	if counter != val {
		t.Fatalf("counter (%d) != val (%d)", counter, val)
	}
}

func TestRender(t *testing.T) {
	counter = 1337
	res := Render("")
	if res != "1337" {
		t.Fatalf("render result %q != %q", res, "1337")
	}
}

